function createSource(rsp) {
  function get(url) {
    const res = rsp.request({ url });
    if (res.status !== 200) throw new Error('HTTP ' + res.status + ': ' + url);
    return res.body;
  }
  return {
    async search(query, page) {
      const data = JSON.parse(get('http://localhost:8123/test/fixtures/demo-search.json'));
      return {
        items: data.data.map((item) => ({ id: item.id, title: item.title, author: item.author })),
        next: null,
      };
    },
    async chapters(work) {
      const data = JSON.parse(get(work.id));
      return data.chapters.map((item) => ({ id: item.id, title: item.title }));
    },
    async pages(chapter) {
      const data = JSON.parse(get(chapter.id));
      return data.images.map((item) => ({ url: item.src }));
    },
  };
}
